-- Pelonot Supabase Schema
-- Run this in the Supabase SQL Editor after creating your project.

-- 1. PROFILES TABLE
CREATE TABLE profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    local_user_id INTEGER UNIQUE,
    name TEXT NOT NULL,
    weight_kg REAL DEFAULT 70.0,
    ftp_watts INTEGER DEFAULT 150,
    theme_preference TEXT DEFAULT 'DARK',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. CLASS TEMPLATES TABLE
CREATE TABLE class_templates (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    duration_sec INTEGER NOT NULL,
    intervals_json JSONB NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. WORKOUTS TABLE (with compressed metrics payload)
CREATE TABLE workouts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
    class_id TEXT REFERENCES class_templates(id) ON DELETE SET NULL,
    duration_sec INTEGER NOT NULL,
    total_output_kj REAL NOT NULL,
    total_distance_km REAL DEFAULT 0,
    avg_cadence REAL,
    avg_power REAL,
    avg_hr REAL,
    intent_modifier REAL DEFAULT 1.0,
    rpe_rating INTEGER,
    metrics_payload JSONB,
    timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- 4. ROW LEVEL SECURITY
-- Enable RLS on all tables
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE class_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE workouts ENABLE ROW LEVEL SECURITY;

-- Allow anon access to read class_templates (public data)
CREATE POLICY "Anyone can read class templates"
    ON class_templates FOR SELECT
    USING (true);

-- Users can read/update only their own profile
CREATE POLICY "Users can read own profile"
    ON profiles FOR SELECT
    USING (true);

CREATE POLICY "Users can update own profile"
    ON profiles FOR UPDATE
    USING (true);

-- Users can read/insert their own workouts
CREATE POLICY "Users can read own workouts"
    ON workouts FOR SELECT
    USING (true);

CREATE POLICY "Users can insert own workouts"
    ON workouts FOR INSERT
    WITH CHECK (true);

-- 5. SEED DATA: 72 Class Templates (7 categories)
